function renderDrills(){
 const mine=LAST?weakAreas(LAST.scores):[];
 if(DF.area==='mine'&&!mine.length)DF.area='all';
 // the list only rebuilds when something it shows has changed, so going back to Drills is instant and the pictures don't reload
 const dkey=JSON.stringify([DF.where,DF.area,mine,mine.length?LAST.scores:0,Hand.get(),DRILLS.length]);
 if(!(dkey===renderDrills.key&&$('drillList').children.length)){renderDrills.key=dkey;
 $('whereChips').innerHTML=[['all','All'],['range','On the range'],['home','At home']].map(([k,l])=>`<button type="button" class="chip${DF.where===k?' on':''}" data-w="${k}">${l}</button>`).join('');
 const areaOpts=(mine.length?[['mine','For my swing']]:[]).concat([['all','All areas']],AREAS.filter(a=>drillsFor(a).length).map(a=>[a,areaName(a)]));
 $('areaChips').innerHTML=areaOpts.map(([k,l])=>`<button type="button" class="chip${DF.area===k?' on':''}" data-a="${esc(k)}">${esc(l)}</button>`).join('');
 $('whereChips').querySelectorAll('button').forEach(b=>b.onclick=()=>{DF.where=b.dataset.w;renderDrills()});
 $('areaChips').querySelectorAll('button').forEach(b=>b.onclick=()=>{DF.area=b.dataset.a;renderDrills()});
 let ds=DRILLS.filter(d=>DF.where==='all'||d.where===DF.where||d.where==='both');
 if(DF.area==='mine'){const best=d=>Math.min(...d.areas.map(a=>mine.includes(a)?LAST.scores[a]:99));ds=ds.filter(d=>d.areas.some(a=>mine.includes(a))).sort((p,q)=>best(p)-best(q))}
 else if(DF.area!=='all')ds=ds.filter(d=>d.areas.includes(DF.area));
 $('drillList').innerHTML=ds.length?ds.map(drillCard).join(''):'<p class="mut">No drills match these filters.</p>';
 posters();}
 renderPlan().catch(e=>console.error(e));$('planTop').hidden=!mine.length;if(mine.length)$('planTop').innerHTML=planHTML(LAST.scores,true);
}
// still pictures for the cards, drawn one at a time as they scroll into view
let posterQ=[],posterBusy=false;
// (the picture itself is hidden until drawn, so watch the box it sits in)
const posterIO=typeof IntersectionObserver!=='undefined'?new IntersectionObserver(es=>es.forEach(e=>{if(e.isIntersecting){posterIO.unobserve(e.target);const im=e.target.querySelector('img[data-poster]');if(im){posterQ.push(im);drainPosters()}}}),{rootMargin:'200px'}):null;
// ready-made pictures ship with the app (tools/posters); drawing in 3D is only the fallback if one is missing
function posters(){const L=Hand.get()==='left';document.querySelectorAll('img[data-poster]').forEach(im=>{if(im.getAttribute('src'))return;
 im.decoding='async';im.onload=()=>{im.hidden=false};im.onerror=()=>{im.onerror=null;im.removeAttribute('src');if(posterIO)posterIO.observe(im.parentElement);else{posterQ.push(im);drainPosters()}};
 im.src='posters/'+im.dataset.poster+(L?'-L':'')+'.jpg'});
 // get the 3D golfer ready while the list is being read, so the first drill opens quickly
 if(!D3P){const pre=()=>load3D().catch(()=>{});document.addEventListener('cc-golfer',warm3D,{once:true});if(window.requestIdleCallback)requestIdleCallback(pre,{timeout:4000});else setTimeout(pre,2500)}}
async function drainPosters(){if(posterBusy)return;posterBusy=true;try{if(!await load3D().catch(()=>false))return;
 while(posterQ.length){const im=posterQ.shift(),d=DRILLS.find(x=>x.id===im.dataset.poster);if(!d||!im.isConnected)continue;
  try{im.src=DrillStudio.poster(d,240,300);im.hidden=false}catch(e){console.error(e)}await new Promise(r=>setTimeout(r,30))}}finally{posterBusy=false}}
// one tiny off-screen drawing sets up the golfer's shaders while the list is being read, so the first drill opens quickly
// It waits until the golfer has stopped scrolling or tapping for a moment, so it never lands mid-swipe.
let LASTIN=0;['scroll','wheel','touchstart','touchmove','pointerdown','keydown'].forEach(e=>addEventListener(e,()=>{LASTIN=performance.now()},{capture:true,passive:true}));
function warm3D(){const ds=[DRILLS.find(d=>d.scene!=='home'),DRILLS.find(d=>d.scene==='home')].filter(Boolean);
 const go=()=>{if(!window.DrillStudio||DP.player)return;if(performance.now()-LASTIN<1500||document.hidden)return setTimeout(idle,700);const d=ds.shift();if(!d)return;try{DrillStudio.poster(d,16,20,true)}catch(e){}idle()},idle=()=>{if(window.requestIdleCallback)requestIdleCallback(go,{timeout:3000});else setTimeout(go,500)};idle()}
// when the realistic golfer arrives, redraw the card pictures with him
document.addEventListener('cc-golfer',()=>{document.querySelectorAll('img[data-poster]').forEach(im=>{if(!im.src||!im.src.startsWith('data:'))return;const r=im.getBoundingClientRect(),vis=r.bottom>-200&&r.top<innerHeight+200&&im.offsetParent;
 if(vis)posterQ.push(im);else{im.removeAttribute('src');if(posterIO)posterIO.observe(im.parentElement);else posterQ.push(im)}});drainPosters()});
