function dpHTML(d){const fx=[...new Set(d.fixes.map(FAULT_TITLE))];
 return `<div class="dpTop"><button type="button" class="dpBack" data-dp-close aria-label="Close drill"><svg viewBox="0 0 24 24" width="22" height="22" aria-hidden="true"><path d="M15 5l-7 7 7 7" fill="none" stroke="currentColor" stroke-width="2.2" stroke-linecap="round" stroke-linejoin="round"/></svg></button><h2 id="dpTitle">${esc(d.name)}</h2></div>
 <div class="dpStageWrap"><div class="dpStage" id="dpStage" role="img" aria-label="3D demonstration of ${esc(d.name)}"></div>
  <div class="dpCtl" role="group" aria-label="Demo controls">
   <button type="button" data-dp="prev" aria-label="Previous step"><svg viewBox="0 0 24 24" width="22" height="22" aria-hidden="true"><path d="M6 5v14M18 5l-9 7 9 7z" fill="currentColor" stroke="currentColor" stroke-width="1.6" stroke-linejoin="round"/></svg></button>
   <button type="button" class="dpPlay" data-dp="play" aria-label="Pause"><svg viewBox="0 0 24 24" width="26" height="26" aria-hidden="true"><path class="pa" d="M7 5h3.5v14H7zM13.5 5H17v14h-3.5z" fill="currentColor"/><path class="pl" d="M7 4.5v15l12.5-7.5z" fill="currentColor"/></svg></button>
   <button type="button" data-dp="next" aria-label="Next step"><svg viewBox="0 0 24 24" width="22" height="22" aria-hidden="true"><path d="M18 5v14M6 5l9 7-9 7z" fill="currentColor" stroke="currentColor" stroke-width="1.6" stroke-linejoin="round"/></svg></button>
   <button type="button" class="dpSpeed" data-dp="speed" aria-pressed="false">Slow-mo</button>
   <select id="dpView" aria-label="Camera angle"><option value="auto">Best angle</option><option value="face">Face-on</option><option value="dtl">Down the line</option><option value="tq">From the side</option><option value="top">From above</option></select>
  </div></div>
 <div class="dpNow" aria-live="polite"><div class="dpDots">${d.steps.map((_,i)=>`<button type="button" data-dp-step="${i}" aria-label="Step ${i+1}"></button>`).join('')}</div><b id="dpStepN"></b><p id="dpStepT"></p><p class="dpFeel" id="dpFeel"></p></div>
 <div class="dpBody">
  <p class="dpWhy">${esc(d.why)}</p>
  <p class="dpBy">${esc(d.by)}</p>
  <div class="dpFacts"><span><b>Where</b>${whereLabel(d.where)}</span><span><b>Kit</b>${esc(d.kit)}</span><span><b>Time</b>${esc(d.time)}</span><span><b>Dose</b>${esc(d.dose)}</span></div>
  <h3>Step by step</h3><ol class="dpSteps">${d.steps.map((s,i)=>`<li><button type="button" data-dp-step="${i}"><span>${i+1}</span><div>${esc(s)}<em>Feel: ${esc(d.feel[i]||'')}</em></div></button></li>`).join('')}</ol>
  ${(d.mistakes||[]).length?`<h3>Common mistakes</h3><ul class="dpMist">${d.mistakes.map(m=>`<li>${esc(m)}</li>`).join('')}</ul>`:''}
  <h3>Fixes</h3><div class="dpFix">${fx.map(f=>`<span>${esc(f)}</span>`).join('')}</div>
  <button type="button" class="liveBtn" data-live="${d.id}"><span class="dot" aria-hidden="true"></span>Practise with live feedback<small>Your camera watches and a voice keeps you in the zone</small></button>
 </div>`}
async function openDrill(id){
 const d=DRILLS.find(x=>x.id===id);if(!d)return;closeDrill(true);
 const el=document.createElement('div');el.className='dpSheet';el.setAttribute('role','dialog');el.setAttribute('aria-modal','true');el.setAttribute('aria-labelledby','dpTitle');el.innerHTML=dpHTML(d);
 document.body.appendChild(el);document.body.classList.add('dpOpen');DP.el=el;DP.d=d;DP.ret=document.activeElement;
 requestAnimationFrame(()=>el.classList.add('in'));el.querySelector('[data-dp-close]').focus();
 const showStep=i=>{if(i==null||i<0)return;$('dpStepN').textContent=`Step ${i+1} of ${d.steps.length}`;$('dpStepT').textContent=d.steps[i];$('dpFeel').textContent=d.feel[i]?'Feel: '+d.feel[i]:'';
  el.querySelectorAll('.dpDots button').forEach((b,k)=>b.classList.toggle('on',k===i));el.querySelectorAll('.dpSteps li').forEach((li,k)=>li.classList.toggle('cur',k===i))};
 showStep(0);
 const ok=await load3D().catch(()=>false);if(DP.d!==d)return;
 if(!ok||!window.DrillStudio){$('dpStage').innerHTML='<p class="mut" style="padding:20px">The 3D demo could not load. Check your connection; the steps below still work.</p>';return}
 const reduce=matchMedia('(prefers-reduced-motion: reduce)').matches;
 DP.player=DrillStudio.Player($('dpStage'),d,{onStep:showStep,paused:reduce});
 const playBtn=el.querySelector('[data-dp=play]'),syncPlay=()=>{playBtn.classList.toggle('paused',!DP.player.playing);playBtn.setAttribute('aria-label',DP.player.playing?'Pause':'Play')};syncPlay();
 el.addEventListener('click',e=>{const b=e.target.closest('[data-dp],[data-dp-step],[data-dp-close]');if(!b||!DP.player)return;
  if(b.dataset.dpClose!=null)return closeDrill();
  if(b.dataset.dpStep!=null){DP.player.goStep(+b.dataset.dpStep);if(b.closest('.dpSteps'))el.querySelector('.dpStageWrap').scrollIntoView({behavior:'smooth',block:'start'});return}
  const a=b.dataset.dp;if(a==='play'){DP.player.toggle();syncPlay()}else if(a==='next')DP.player.next();else if(a==='prev')DP.player.prev();
  else if(a==='speed'){const on=b.getAttribute('aria-pressed')!=='true';b.setAttribute('aria-pressed',on);DP.player.setSpeed(on?0.45:1)}});
 $('dpView').onchange=e=>DP.player.setView(e.target.value);
 el.addEventListener('keydown',e=>{if(e.key==='Escape')closeDrill();if(e.key===' '&&e.target===el){e.preventDefault();DP.player.toggle();syncPlay()}});
}
function closeDrill(quiet){if(DP.player){DP.player.destroy();DP.player=null}if(DP.el){const el=DP.el;el.classList.remove('in');setTimeout(()=>el.remove(),quiet?0:220)}
 document.body.classList.remove('dpOpen');const r=DP.ret;DP.el=null;DP.d=null;DP.ret=null;if(!quiet&&r&&r.focus)r.focus()}
document.addEventListener('click',e=>{const b=e.target.closest('[data-open]');if(b){e.preventDefault();openDrill(b.dataset.open)}});

