async function renderSetup(){
 $('clubPick').innerHTML=CLUB_GROUPS.map(([g,ids])=>`<div class="grp"><span>${g}</span>${ids.map(id=>`<button type="button" role="radio" aria-checked="${id===SUCLUB}" data-club="${id}">${CLUB_SHORT[id]||(/^\d\d$/.test(id)?id+'°':id)}</button>`).join('')}</div>`).join('');
 $('setupCard').innerHTML='<p class="mut">Loading…</p>';
 try{await loadSetup()}catch(_){$('setupCard').innerHTML='<p class="mut">Setup guide could not load. Check your connection.</p>';return}
 const SC=window.SetupCoach,club=SC.CLUBS.find(c=>c.id===SUCLUB)||SC.CLUBS[11];let h=175;try{h=+(localStorage.getItem('cc_height')||175)}catch(_){}
 const d=SC.describe(club,h),t=d.t;
 // top-down view as you stand over the ball, looking down: a right-hander's target is on the left, a left-hander's on the right
 const RH=Hand.get()!=='left',X=x=>RH?340-x:x,A=a=>RH?(a==='end'?'start':a==='start'?'end':a):a,fr=r=>RH?-r:r;
 const sw=110,W=(t.width[0]+t.width[1])/2*sw,cx=170,fy=178,tx=cx-W/2,lx=cx+W/2,b=(t.ball[0]+t.ball[1])/2,bx=tx+b*W,by=fy-58-(1-club.c)*30;
 const foot=(x,rot)=>`<g transform="translate(${X(x)} ${fy}) rotate(${fr(rot)})"><rect x="-11" y="-30" width="22" height="58" rx="11" fill="var(--chip)" stroke="var(--tx)" stroke-width="2"/><circle cx="0" cy="18" r="3" fill="var(--tx)" opacity=".5"/></g>`;
 const svg=`<svg class="suFig" viewBox="0 ${by-48} 340 ${fy+90-(by-48)}" role="img" aria-label="Looking down at your setup for a ${esc(club.name)}, ${RH?'right':'left'}-handed, target on the ${RH?'left':'right'}: ball ${esc(d.ball.toLowerCase())}, stance ${esc(d.stance.toLowerCase())}">
  <path d="M${X(20)} ${by} L${X(300)} ${by}" stroke="var(--mut)" stroke-width="1.5" stroke-dasharray="5 5"/><path d="M${X(300)} ${by} l${RH?10:-10} -6 v12 z" fill="var(--mut)"/><text x="${X(304)}" y="${by+4}" text-anchor="${A('start')}" fill="var(--mut)">Target</text>
  <path d="M${X(20)} ${fy-34} L${X(300)} ${fy-34}" stroke="var(--bd)" stroke-width="1.5" stroke-dasharray="3 5"/><text x="${X(22)}" y="${fy-40}" text-anchor="${A('start')}" fill="var(--mut)">Toe line, parallel</text>
  <path d="M${cx} ${by-30} L${cx} ${fy+40}" stroke="var(--bd)" stroke-width="1" stroke-dasharray="2 4"/><text x="${cx}" y="${by-34}" text-anchor="middle" fill="var(--mut)">Centre</text>
  <path d="M${cx-sw/2} ${fy+56} v-8 M${cx+sw/2} ${fy+56} v-8 M${cx-sw/2} ${fy+52} H${cx+sw/2}" stroke="var(--mut)" stroke-width="1.5"/><text x="${cx}" y="${fy+67}" text-anchor="middle" fill="var(--mut)">Shoulder width</text>
  ${foot(tx,-4)}${foot(lx,24)}
  <text x="${X(tx-16)}" y="${fy+42}" text-anchor="${A('end')}" fill="var(--tx)">Back foot</text><text x="${X(lx+22)}" y="${fy+42}" text-anchor="${A('start')}" fill="var(--tx)">Front foot</text>
  <path d="M${X(bx)} ${by} L${X(bx)} ${fy-34}" stroke="var(--good)" stroke-width="1.5" stroke-dasharray="3 3"/>
  <circle cx="${X(bx)}" cy="${by}" r="7" fill="#fff" stroke="var(--tx)" stroke-width="1.5"/>
  <text x="${X(bx)}" y="${by-14}" text-anchor="middle" fill="var(--good)">Ball</text>
  <text x="${cx}" y="${fy+84}" text-anchor="middle" fill="var(--mut)">As you look down at the ball (${RH?'right':'left'}-handed)</text>
 </svg>`;
 $('setupCard').innerHTML=`<h2>Your setup for the ${esc(club.name)}</h2><div class="suWrap">${svg}<ul class="suList">
  <li><b>Ball</b><span>${esc(d.ball)}</span></li><li><b>Stance</b><span>${esc(d.stance)}, lead foot flared out 20–30°, trail foot square or a touch out</span></li>
  <li><b>Distance</b><span>${esc(d.dist)}</span></li><li><b>Posture</b><span>${esc(d.posture)}</span></li>
  <li><b>Shoulders</b><span>${esc(d.tilt)}, parallel to the target line</span></li><li><b>Head</b><span>${esc(d.head)}</span></li>
  <li><b>Hands</b><span>${esc(d.hands)}</span></li><li><b>Weight</b><span>${esc(d.weight)}</span></li></ul></div>`;
}
