function drillChips(area){return pickPair(area).map(d=>`<button type="button" class="chip" data-drill="${d.id}">${esc(d.name)} · ${whereLabel(d.where)}</button>`).join('')}
function planHTML(scores,inDrills){
 const w=weakAreas(scores).slice(0,3);
 if(!w.length)return `<h2>Your practice plan</h2><p class="mut" style="margin:0">Every measured area scored 8 or more. Keep using "Hold the finish" and the tempo count to stay sharp.</p>`;
 return `<h2>Your practice plan</h2><p class="mut" style="margin:0 0 8px">Your lowest-scoring areas, each with a range drill and one you can do at home. Tap a drill for the steps.</p>
 <div class="list">${w.map(a=>`<div><div class="row" style="justify-content:space-between"><b>${esc(areaName(a))}</b><span class="pill g-${grade(scores[a])}">${scores[a]}/10</span></div><div class="chips" style="margin-top:6px">${drillChips(a)}</div></div>`).join('')}</div>
 ${inDrills?'':'<p style="margin:10px 0 0"><button type="button" class="link" data-tab3>Open the drill library</button></p>'}`;
}
