const userTrim=f=>()=>{TR.user=true;if(busy&&TR.finding){TR.find++}f()};
$('trimA').oninput=userTrim(()=>setTrim($('trimA').value/1000*v.duration,TR.b,'a'));
$('trimB').oninput=userTrim(()=>setTrim(TR.a,$('trimB').value/1000*v.duration,'b'));
$('setA').onclick=userTrim(()=>setTrim(v.currentTime,TR.b,'a'));
$('setB').onclick=userTrim(()=>setTrim(TR.a,v.currentTime,'b'));
$('findSwing').onclick=()=>{if(!busy)findSwing(job)};
$('go').onclick=()=>{if(!busy&&TR.b-TR.a<=MAXLEN+0.01)analyze(job)};
try{if(localStorage.getItem('cc_saveclip')==='0')$('saveClip').checked=false}catch(_){}
$('saveClip').onchange=()=>{try{localStorage.setItem('cc_saveclip',$('saveClip').checked?'1':'0')}catch(_){}};
v.addEventListener('timeupdate',()=>{if(!busy&&!v.paused&&TR.b>TR.a&&!$('trimBox').hidden&&v.currentTime>TR.b+0.05)v.currentTime=TR.a});

// ---------- frame helpers ----------
async function seek(t){
 t=Math.max(0,Math.min(v.duration-0.03,t));
 await new Promise(res=>{let d=false;const f=()=>{if(d)return;d=true;v.removeEventListener('seeked',f);clearTimeout(to);res()};const to=setTimeout(f,5000);v.addEventListener('seeked',f);v.currentTime=t});
 let mt=null;
 if(v.requestVideoFrameCallback)await Promise.race([new Promise(r=>v.requestVideoFrameCallback((n,m)=>{mt=m&&m.mediaTime;r()})),sleep(120)]);else await sleep(40);
 return mt!=null&&Math.abs(mt-t)<0.1?mt:v.currentTime;
}
function dims(){const vw=v.videoWidth,vh=v.videoHeight,sc=Math.min(1,640/Math.max(vw,vh));return{W:Math.round(vw*sc),H:Math.round(vh*sc)}}
function frameCanvas(W,H){const c=document.createElement('canvas');c.width=W;c.height=H;c.getContext('2d').drawImage(v,0,0,W,H);return c}
function makeSampler(){
 const c=document.createElement('canvas'),x=c.getContext('2d',{willReadFrequently:true});
 return src=>(dst,S,roi,lo,hi)=>{
  if(c.width!==S){c.width=S;c.height=S}
  x.setTransform(1,0,0,1,0,0);x.fillStyle='#000';x.fillRect(0,0,S,S);
  x.translate(S/2,S/2);x.rotate(-roi.rot);x.scale(S/roi.w,S/roi.h);x.translate(-roi.cx,-roi.cy);x.drawImage(src,0,0);
  const d=x.getImageData(0,0,S,S).data,k=(hi-lo)/255;
  for(let i=0,j=0;i<S*S;i++,j+=4){dst[i*3]=lo+k*d[j];dst[i*3+1]=lo+k*d[j+1];dst[i*3+2]=lo+k*d[j+2]}
 };
}
// several background threads tracking at once on phones with more than one core (falls back to this page if not)
const PW={workers:null,ok:null,seq:0,
 n(){const c=navigator.hardwareConcurrency||2;return Math.max(1,Math.min(4,c-1))},
 async init(){if(this.ok!=null)return this.ok;try{if(typeof Worker==='undefined'||typeof OffscreenCanvas==='undefined'||!window.createImageBitmap||this.n()<2)return this.ok=false;
   this.workers=Array.from({length:this.n()},()=>new Worker('posework.js'));
   await Promise.race([Promise.all(this.workers.map(w=>this.call(w,{type:'warm'}))),sleep(30000).then(()=>{throw new Error('slow')})]);this.ok=true}
  catch(e){console.warn('Tracking in the background is unavailable here:',e);(this.workers||[]).forEach(w=>w.terminate());this.workers=null;this.ok=false}return this.ok},
 call(w,msg,onProg){const id=++this.seq;return new Promise((res,rej)=>{const f=e=>{const d=e.data;if(d.id!==id)return;if(d.progress){onProg&&onProg();return}w.removeEventListener('message',f);w.removeEventListener('error',g);d.ok?res(d.out||[]):rej(new Error(d.err))},g=e=>{w.removeEventListener('message',f);w.removeEventListener('error',g);rej(e)};w.addEventListener('message',f);w.addEventListener('error',g);w.postMessage(Object.assign({id},msg))})}};
let POSE=null;
async function getPose(){
 if(POSE)return POSE;
 if(!window.POSE_MODELS)await new Promise((res,rej)=>{const s=document.createElement('script');s.src='models.js';s.onload=res;s.onerror=()=>rej({code:'model_load'});document.head.appendChild(s)});
 const ab=s=>{const b=atob(s),u=new Uint8Array(b.length);for(let i=0;i<b.length;i++)u[i]=b.charCodeAt(i);return u.buffer};
 POSE=new BlazePose.Pose(ab(POSE_MODELS.det),ab(POSE_MODELS.lm));return POSE;
}

// frames at the given times: play the video at speed and keep the frame nearest each time; jump to any it missed
async function grabAt(times,W,H,live,onProg){const out=times.map(t=>({t,c:null,dt:1e9}));
 if(v.requestVideoFrameCallback&&times.length>2){const a=Math.max(0,times[0]-0.05),b=times[times.length-1]+0.05;await seek(a);
  await new Promise(res=>{let done=false;const fin=()=>{if(done)return;done=true;clearTimeout(to);v.pause();v.playbackRate=1;res()};
   const to=setTimeout(fin,(b-a)/2*1000+6000);v.addEventListener('ended',fin,{once:true});
   const cb=(now,meta)=>{if(done)return;if(!live())return fin();const mt=meta.mediaTime;
    // the time slot this frame is closest to; keep it if it's the closest seen yet
    let k=0,bd=1e9;for(let i=0;i<out.length;i++){const dd=Math.abs(out[i].t-mt);if(dd<bd){bd=dd;k=i}}
    if(bd<out[k].dt&&bd<0.12){out[k].dt=bd;out[k].t=mt;if(!out[k].c)out[k].c=document.createElement('canvas');const c=out[k].c;c.width=W;c.height=H;c.getContext('2d').drawImage(v,0,0,W,H)}
    if(onProg)onProg(Math.min(1,(mt-a)/(b-a)));if(mt>=b)fin();else v.requestVideoFrameCallback(cb)};
   v.requestVideoFrameCallback(cb);try{v.playbackRate=4}catch(_){}
   v.muted=true;const p=v.play();if(p&&p.catch)p.catch(fin)})}
 for(const o of out){if(!live())break;if(!o.c){o.t=await seek(o.t);o.c=frameCanvas(W,H)}}
 return out}
// ---------- Find my swing (suggests a trim) ----------
async function findSwing(my){
 const tok=++TR.find;busy=true;TR.finding=true;$('go').disabled=true;$('findSwing').disabled=true;
 const live=()=>my===job&&tok===TR.find;
 try{
  say('Finding your swing… (drag the handles at any time to choose it yourself)');prog(.02);
  const pose=await getPose();if(!live())return;
  const {W,H}=dims(),d=v.duration,sampler=makeSampler();
  const n=Math.max(8,Math.min(48,Math.round(d*3))),times=Array.from({length:n},(_,i)=>d*(i+.5)/n),fr=[];let roi=null;
  // grab the frames by playing the video quickly (much faster than jumping to each one), then look for the golfer in each
  const cs=await grabAt(times,W,H,live,f=>prog(.02+.25*f));if(!live())return;
  for(let i=0;i<n;i++){
   if(!live())return;
   const r=pose.track({width:W,height:H},roi,sampler(cs[i].c));roi=r?r.next:null;
   fr.push(r?{t:cs[i].t,pts:r.pts,world:r.world}:{t:cs[i].t});
   prog(.27+.7*(i+1)/n);await tick();
  }
  const win=SwingMetrics.findWindow(fr);
  if(!live())return;
  if(!win){say("Couldn't spot a swing automatically. Drag the handles to the swing, then tap Trim and analyse.");return}
  let a=Math.max(0,win.t0+0.2),b=Math.min(d,win.t1);if(b-a>MAXLEN)b=a+MAXLEN;
  busy=false;setTrim(a,b,'a');
  say(`Swing found at ${a.toFixed(1)}–${b.toFixed(1)}s. Check the trim, then tap Trim and analyse.`);
 }catch(e){if(live())say("Couldn't spot a swing automatically. Drag the handles to the swing, then tap Trim and analyse.")}
 finally{if(my===job&&tok===TR.find){busy=false;TR.finding=false;prog(null);$('findSwing').disabled=false;trimUI()}else if(my===job&&!TR.finding){}
  if(my===job&&tok!==TR.find){TR.finding=false;busy=false;prog(null);$('findSwing').disabled=false;trimUI();say('Trim set by hand. Tap Trim and analyse when ready.')}}
}

// ---------- capture the trimmed clip, discard the rest ----------
async function captureClip(my,a,b){
 const {W,H}=dims(),out=[];
 const enc=c=>new Promise(r=>c.toBlob(r,'image/jpeg',.85));
 if(v.requestVideoFrameCallback){
  await seek(Math.max(0,a-0.05));
  const pend=[];
  await new Promise(res=>{
   let done=false,last=-1;const fin=()=>{if(done)return;done=true;clearTimeout(to);v.pause();v.playbackRate=1;res()};
   const to=setTimeout(fin,(b-a)/0.5*1000+8000);
   v.addEventListener('ended',fin,{once:true});
   const cb=(now,meta)=>{if(done)return;if(my!==job)return fin();const mt=meta.mediaTime;
    if(mt>=a-0.001&&mt<=b+0.001&&mt-last>=1/32){last=mt;const c=frameCanvas(W,H);pend.push(enc(c).then(blob=>({t:mt,blob})))}
    prog(.02+.1*Math.min(1,Math.max(0,(mt-a)/(b-a))));
    if(mt>=b)fin();else v.requestVideoFrameCallback(cb)};
   v.requestVideoFrameCallback(cb);
   try{v.playbackRate=0.5}catch(_){}
   const p=v.play();if(p&&p.catch)p.catch(fin);
  });
  out.push(...(await Promise.all(pend)).filter(f=>f.blob));
 }
 out.sort((p,q)=>p.t-q.t);
 const want=[];
 if(out.length<3){for(let t=a;t<=b;t+=1/30)want.push(t)}
 else{const pts=[a-1/60].concat(out.map(f=>f.t),[b+1/60]);for(let i=1;i<pts.length;i++)if(pts[i]-pts[i-1]>0.05)for(let t=pts[i-1]+1/30;t<pts[i]-0.017;t+=1/30)want.push(t)}
 for(let i=0;i<want.length;i++){if(my!==job)return null;const t=await seek(want[i]);out.push({t,blob:await enc(frameCanvas(W,H))});prog(.12+.03*(i+1)/want.length)}
 out.sort((p,q)=>p.t-q.t);
 const uniq=out.filter((f,i)=>f.blob&&(i===0||f.t-out[i-1].t>0.005)),t0=uniq.length?uniq[0].t:a;
 return {W,H,frames:uniq.map(f=>({t:f.t-t0,blob:f.blob})),src:{a,b}};
}
function releaseOriginal(){
 v.pause();const u=v.src;v.removeAttribute('src');v.load();if(u&&u.startsWith('blob:'))URL.revokeObjectURL(u);
 $('videoCard').hidden=true;$('trimBox').hidden=true;
}

// ---------- frame player ----------
const BMP=new Map();
async function bmp(i){if(BMP.has(i))return BMP.get(i);const b=await createImageBitmap(CLIP.frames[i].blob);BMP.set(i,b);if(BMP.size>48){const k=BMP.keys().next().value;const o=BMP.get(k);BMP.delete(k);if(o&&o.close)o.close()}return b}
const PL={i:0,playing:false,rate:1,raf:0,t0:0,c0:0};
function setupPlayer(){
 $('playerCard').hidden=false;
 const r=CLIP.W/CLIP.H,w=(pc.parentElement.clientWidth||348)-28,mh=window.innerHeight*0.62;let cw=w,ch=cw/r;if(ch>mh){ch=mh;cw=ch*r}
 const dpr=window.devicePixelRatio||1;pc.width=Math.round(cw*dpr);pc.height=Math.round(ch*dpr);pc.style.width=cw+'px';pc.style.height=ch+'px';pc.style.margin='0 auto';
 $('scrub').max=CLIP.frames.length-1;showFrame(PL.i||0);
}
async function showFrame(i){
 if(!CLIP)return;i=Math.max(0,Math.min(CLIP.frames.length-1,i));PL.i=i;$('scrub').value=i;
 const b=await bmp(i);if(PL.i!==i)return;
 const x=pc.getContext('2d');x.setTransform(1,0,0,1,0,0);x.drawImage(b,0,0,pc.width,pc.height);
 if(RES&&RES.byFrame&&$('mode').value!=='off'){const k=pc.width/CLIP.W,d=RES.byFrame.get(i)||RES.nearest(CLIP.frames[i].t);
  if(d){const map=p=>[p.x*k,p.y*k],lw=Math.max(2,pc.width/180);const M=d.me.map(map),D=d.id&&d.id.map(map),both=$('mode').value==='both'&&D;if(both)drawPose(x,D,'ideal',lw);drawPose(x,M,'me',lw);if(both)arrows(x,M,D,lw,RES.T0*k)}}
}
function stopPlay(){PL.playing=false;cancelAnimationFrame(PL.raf);$('play').textContent='Play'}
$('play').onclick=()=>{if(!CLIP)return;if(PL.playing){stopPlay();return}PL.playing=true;$('play').textContent='Pause';
 if(PL.i>=CLIP.frames.length-1)PL.i=0;PL.t0=performance.now();PL.c0=CLIP.frames[PL.i].t;
 const end=CLIP.frames[CLIP.frames.length-1].t;
 const loop=async()=>{if(!PL.playing)return;let ct=PL.c0+(performance.now()-PL.t0)/1000*PL.rate;
  if(ct>end+0.4){PL.t0=performance.now();PL.c0=0;ct=0}
  let i=0;while(i<CLIP.frames.length-1&&CLIP.frames[i+1].t<=ct)i++;
  await showFrame(i);if(PL.playing)PL.raf=requestAnimationFrame(loop)};loop()};
$('back').onclick=()=>{stopPlay();showFrame(PL.i-1)};$('fwd').onclick=()=>{stopPlay();showFrame(PL.i+1)};
$('scrub').oninput=()=>{stopPlay();showFrame(+$('scrub').value)};
$('slow').onclick=()=>{PL.rate=PL.rate===1?0.25:1;$('slow').classList.toggle('on',PL.rate!==1);if(PL.playing){PL.t0=performance.now();PL.c0=CLIP.frames[PL.i].t}};
$('mode').onchange=()=>showFrame(PL.i);
window.addEventListener('resize',()=>{if(CLIP&&!$('playerCard').hidden)setupPlayer()});

// ---------- drawing ----------
const BONES=[[11,12],[11,13],[13,15],[12,14],[14,16],[11,23],[12,24],[23,24],[23,25],[25,27],[24,26],[26,28],[27,31],[28,32],[27,29],[28,30]];
function drawPose(x,P,kind,lw){
 const neck=[(P[11][0]+P[12][0])/2,(P[11][1]+P[12][1])/2],hip=[(P[23][0]+P[24][0])/2,(P[23][1]+P[24][1])/2];
 x.save();x.lineCap='round';x.lineJoin='round';
 if(kind==='ideal'){x.setLineDash([lw*2.2,lw*1.6]);x.strokeStyle='rgba(47,212,111,.95)';x.lineWidth=lw*1.6}else x.lineWidth=lw;
 // your body: a dark edge under every line so it reads on any background, then lead side white and trail side flag yellow
 if(kind==='me'){x.strokeStyle='rgba(8,24,16,.55)';x.lineWidth=lw*2.1;for(const [a,b] of BONES){x.beginPath();x.moveTo(P[a][0],P[a][1]);x.lineTo(P[b][0],P[b][1]);x.stroke()}
  x.beginPath();x.moveTo(hip[0],hip[1]);x.lineTo(neck[0],neck[1]);x.lineTo(P[0][0],P[0][1]);x.stroke();x.lineWidth=lw*1.15}
 for(const [a,b] of BONES){if(kind==='me')x.strokeStyle=a%2?'rgba(255,255,255,.96)':'rgba(243,196,58,.96)';x.beginPath();x.moveTo(P[a][0],P[a][1]);x.lineTo(P[b][0],P[b][1]);x.stroke()}
 if(kind==='me')x.strokeStyle='rgba(255,255,255,.96)';
 x.beginPath();x.moveTo(hip[0],hip[1]);x.lineTo(neck[0],neck[1]);x.lineTo(P[0][0],P[0][1]);x.stroke();
 x.setLineDash([]);const hr=Math.hypot(P[7][0]-P[8][0],P[7][1]-P[8][1])*0.7+lw*2;
 x.beginPath();x.arc(P[0][0],P[0][1],hr,0,7);x.stroke();
 if(kind==='me'){for(const i of [11,12,13,14,15,16,23,24,25,26,27,28]){x.beginPath();x.arc(P[i][0],P[i][1],lw*1.05,0,7);x.fillStyle='#0f3d2b';x.fill();x.lineWidth=lw*.55;x.strokeStyle='#fff';x.stroke()}}
 x.restore();
}
function arrows(x,A,B,lw,T){
 x.save();x.strokeStyle='#fff';x.fillStyle='#fff';x.lineWidth=lw*0.9;x.shadowColor='rgba(0,0,0,.7)';x.shadowBlur=3;
 for(const g of [[0],[11,12],[23,24],[13],[14],[15,16]]){
  const a=[g.reduce((s,i)=>s+A[i][0],0)/g.length,g.reduce((s,i)=>s+A[i][1],0)/g.length],b=[g.reduce((s,i)=>s+B[i][0],0)/g.length,g.reduce((s,i)=>s+B[i][1],0)/g.length];
  const d=Math.hypot(b[0]-a[0],b[1]-a[1]);if(d<Math.max(T*0.045,lw*3))continue;
  const ang=Math.atan2(b[1]-a[1],b[0]-a[0]),h=Math.min(lw*4,d*.5);
  x.beginPath();x.moveTo(a[0],a[1]);x.lineTo(b[0]-Math.cos(ang)*h*.6,b[1]-Math.sin(ang)*h*.6);x.stroke();
  x.beginPath();x.moveTo(b[0],b[1]);x.lineTo(b[0]-Math.cos(ang-.5)*h,b[1]-Math.sin(ang-.5)*h);x.lineTo(b[0]-Math.cos(ang+.5)*h,b[1]-Math.sin(ang+.5)*h);x.closePath();x.fill()}
 x.restore();
}
function keyThumb(src,me,id,T0,w,h,q){
 const all=me.concat(id||[]),xs=all.map(p=>p.x),ys=all.map(p=>p.y);let x0=Math.min(...xs),x1=Math.max(...xs),y0=Math.min(...ys),y1=Math.max(...ys);
 let cx=(x0+x1)/2,cy=(y0+y1)/2,ch=(y1-y0)*1.25,cw=ch*w/h;if((x1-x0)*1.25>cw){cw=(x1-x0)*1.25;ch=cw*h/w}
 if(src){if(cw<=src.width)cx=Math.min(Math.max(cx,cw/2),src.width-cw/2);if(ch<=src.height)cy=Math.min(Math.max(cy,ch/2),src.height-ch/2)}
 const c=document.createElement('canvas');c.width=w;c.height=h;const x=c.getContext('2d');x.fillStyle='#0d130f';x.fillRect(0,0,w,h);
 const k=w/cw,map=p=>[(p.x-(cx-cw/2))*k,(p.y-(cy-ch/2))*k];
 if(src)x.drawImage(src,cx-cw/2,cy-ch/2,cw,ch,0,0,w,h);
 const lw=Math.max(1.6,w/110),M=me.map(map),D=id&&id.map(map);if(D)drawPose(x,D,'ideal',lw);drawPose(x,M,'me',lw);if(D)arrows(x,M,D,lw,T0*k)
 return c.toDataURL('image/jpeg',q||.8);
}

// ================= ANALYSIS =================
function opts(){return{hand:$('hand').value||undefined,view:$('view').value||undefined}}
['hand','view'].forEach(id=>$(id).onchange=()=>{if(RES&&RES.R&&!busy)finishAnalysis(job,true)});
async function analyze(my){
 if(busy)return;if(typeof plusGate==='function'&&!(await plusGate('swing')))return;busy=true;$('go').disabled=true;stopPlay();
 try{
  step(1);say('Keeping only your trimmed clip…');prog(.01);
  const clip=await captureClip(my,TR.a,TR.b);if(!clip||my!==job)return;
  if(clip.frames.length<10){say('Too few frames could be read from the trimmed part. Try a longer trim or another video.',true);prog(null);return}
  releaseOriginal();BMP.clear();CLIP=clip;RES=null;PL.i=0;setupPlayer();
  $('clipInfo').textContent=`Trimmed clip: ${(CLIP.frames[CLIP.frames.length-1].t).toFixed(1)} s, ${CLIP.frames.length} frames. The rest of the video has been discarded from Caddy Coach; your original stays in your camera roll.`;
  step(2);say('Loading the body-tracking model…');
  const pose=await getPose();if(my!==job)return;
  const sampler=makeSampler(),{W,H}=CLIP,N=CLIP.frames.length,dense=[],done=new Set();let count=0;const t1=performance.now();
  const run=async(idx,total,base,span,lab)=>{
   let r0=null,prevI=-9;
   for(let k=0;k<idx.length;k++){
    const i=idx[k];if(my!==job)return false;
    if(i-prevI>2||!r0){const prev=dense.filter(f=>f.i<i).pop();r0=prev?prev.roi:null}
    const b=await bmp(i);const r=pose.track({width:W,height:H},r0,sampler(b));r0=r?r.next:null;prevI=i;done.add(i);
    if(r)dense.push({i,t:CLIP.frames[i].t,pts:r.pts,world:r.world,roi:r.roi});
    count++;const per=(performance.now()-t1)/count;
    const left=Math.max(1,Math.round(per*(total-count)/1000));
    say(lab?`${lab} (about ${left} s)…`:`Tracking your body ${count}/${total} (about ${left} s left)…`);prog(base+span*(k+1)/idx.length);await tick();
   }
   dense.sort((p,q)=>p.t-q.t);return true;
  };
  const idxA=[];for(let i=0;i<N;i+=2)idxA.push(i);
  // the first look: every other frame (split between background threads where the phone has the cores)
  const par=await PW.init().catch(()=>false);if(my!==job)return;
  const runPar=async(idx,total,base,span,lab,chain)=>{const K=PW.workers.length,parts=[];
   if(chain){const per=Math.ceil(idx.length/K);for(let k=0;k<K;k++){const a=idx.slice(k*per,(k+1)*per);if(a.length)parts.push(a)}}
   else{for(let k=0;k<K;k++)parts.push(idx.filter((_,q)=>q%K===k))}
   const t0=performance.now();let doneN=0;
   const res=await Promise.all(parts.map((a,k)=>PW.call(PW.workers[k],{chain,W,H,jobs:a.map(i=>({i,blob:CLIP.frames[i].blob,roi:chain?null:((dense.filter(f=>f.i<i).pop()||{}).roi||null)}))},()=>{count++;doneN++;const per=(performance.now()-t0)/doneN,left=Math.max(1,Math.round(per*(idx.length-doneN)/1000));if(my===job){say(lab?`${lab} (about ${left} s)…`:`Tracking your body ${count}/${total} (about ${left} s left)…`);prog(base+span*doneN/idx.length)}})));
   if(my!==job)return false;
   for(const r of res)for(const x of r){done.add(x.i);if(x.r)dense.push({i:x.i,t:CLIP.frames[x.i].t,pts:x.r.pts,world:x.r.world,roi:x.r.roi})}
   dense.sort((p,q)=>p.t-q.t);return true};
  if(par){try{if(!await runPar(idxA,idxA.length+16,.15,.6,null,true))return}catch(e){console.warn(e);PW.ok=false;dense.length=0;done.clear();count=0;if(!await run(idxA,idxA.length+16,.15,.6))return}}
  else if(!await run(idxA,idxA.length+16,.15,.6))return;
  if(dense.length<5){say('No golfer was found in the trimmed clip. Make sure your whole body is in view and well lit.',true);prog(null);return}
  step(3);
  const A2=SwingMetrics.analyse(dense,opts());
  if(!A2.ok){say("Your body was tracked, but a full swing (top, impact and finish) wasn't found in the trim. Upload the video again and include the whole swing.",true);prog(null);return}
  const idxB=[];const zone=(x0,x1)=>CLIP.frames.forEach((f,i)=>{if(f.t>=x0&&f.t<=x1&&!done.has(i)&&!idxB.includes(i))idxB.push(i)});
  // every frame from just before the takeaway to just after the finish, so the result doesn't depend on which frames the first pass happened to see
  zone(A2.times.takeaway-0.6,A2.times.finish+0.4);idxB.sort((p,q)=>p-q);
  // your results straight away from the first pass; then a closer look at the moments that matter refines them
  RES={dense:dense.slice()};await finishAnalysis(my,'preview');if(my!==job)return;
  if(PW.ok){try{if(!await runPar(idxB,count+idxB.length,.75,.15,'Your results are below. Fine-tuning the key moments',false))return}catch(e){console.warn(e);if(!await run(idxB,count+idxB.length,.75,.15,'Your results are below. Fine-tuning the key moments'))return}}
  else if(!await run(idxB,count+idxB.length,.75,.15,'Your results are below. Fine-tuning the key moments'))return;
  RES={dense};await finishAnalysis(my,false);
 }catch(e){if(my!==job)return;prog(null);console.error(e);
  say(e&&e.code==='model_load'?'The body-tracking model could not be loaded. Check your connection and try again.':'The analysis stopped ('+((e&&(e.code||e.message))||'unknown error')+'). Upload the video and try again.',true)}
 finally{if(my===job){busy=false;if(!CLIP)trimUI()}}
}

async function finishAnalysis(my,quick){
 const dense=RES.dense;
 const R=SwingMetrics.analyse(dense,opts());
 if(!R.ok){say('The swing could not be measured reliably from this clip. Try a steadier camera with your whole body in view.',true);prog(null);return}
 const I=IdealPose.build(dense,R);
 RES.R=R;RES.I=I;RES.T0=I.T0;RES.byFrame=new Map();dense.forEach((f,k)=>RES.byFrame.set(f.i,{me:f.pts,id:I.ideal[k]}));
 RES.nearest=t=>{let b=0,bd=1e9;dense.forEach((f,k)=>{const d=Math.abs(f.t-t);if(d<bd){bd=d;b=k}});return bd<0.05?{me:dense[b].pts,id:I.ideal[b]}:null};
 const T=R.times,items=[['Address',T.address],['Takeaway',T.takeaway],['Top',T.top],['Downswing',(T.top+T.impact)/2],['Impact',T.impact],['Finish',T.finish]];
 if(I.headAt!=null){const lab=Object.keys(I.notes).find(k=>I.notes[k].some(n=>n.area==='Head stability'));const it=items.find(x=>x[0]===lab);if(it)it[1]=I.headAt}
 const keys=[];
 for(const [lab,t] of items){let bk=0;dense.forEach((f,k)=>{if(Math.abs(f.t-t)<Math.abs(dense[bk].t-t))bk=k});const f=dense[bk];const b=await bmp(f.i);
  keys.push({lab,t:f.t,fi:f.i,notes:I.notes[lab]||[],img:keyThumb(b,f.pts,I.ideal[bk],I.T0,240,320,.8),small:keyThumb(b,f.pts,I.ideal[bk],I.T0,150,200,.66)})}
 RES.keys=keys;RES.text=localText(R);renderLive();
 {const tips=filmCheck(dense,CLIP.W,CLIP.H),ft=$('filmTip');if(ft){ft.hidden=!tips.length;ft.innerHTML=tips.length?`<div class="card fgCheck"><b>Filming tip for next time</b>${tips.map(t=>`<p>${esc(t)}</p>`).join('')}</div>`:''}}
 step(4);prog(null);showFrame(keys[0].fi);
 if(quick==='preview'){say('Your results are below. Fine-tuning the key moments…');prog(.75);return}
 if(quick){say('Updated.');return}
 say('Measured. Writing your coaching notes…');
 const t=await coachText(R).catch(()=>null);if(my!==job)return;
 if(t){const loc=localText(R),by={};t.categories.forEach(c=>{if(c&&c.name)by[c.name]=c});t.categories=AREAS.map(k=>Object.assign({},loc.categories.find(c=>c.name===k),k.startsWith('Clubface')&&/traced shot/.test((loc.categories.find(c=>c.name===k)||{}).finding||'')?{}:(by[k]||{})));if(!t.summary)t.summary=loc.summary;if(!t.top_priority)t.top_priority=loc.top_priority;RES.text=t;renderLive()}
 say('Saving to your swing history…');
 const saved=await saveAnalysis().catch(e=>{console.error(e);return null});
 if(typeof track==='function')track('swing');if(typeof ccNotify==='function')ccNotify('Your swing analysis is ready','Overall score '+R.scores.overall+'/10. Tap to see what to work on.');
 say((t||!HOSTED_IN_CLAUDE?'Done. ':'Done (coaching notes are built in because Claude was not available here). ')+(saved?`Saved to your swing history${saved.hasClip?' with the trimmed clip':''}.${saved.clipNote}`:'This round could not be saved.')+' Play the clip to compare your swing with the better position.');
}

// clubface and path: body tracking can't see the face, so use the last shot traced in the last 30 days and
// compare it with what the swing shows about the hand path
function clubfaceArea(k,m){let f=null;try{f=JSON.parse(localStorage.getItem('cc_lastflight')||'null')}catch(_){}
 const ott=m&&m.hand_path_out!=null&&m.hand_path_out>0.03,inside=m&&m.hand_path_out!=null&&m.hand_path_out<=0.01;
 if(!f||Date.now()-f.t>30*864e5)return{name:k,finding:"Clubface and path can't be seen by body tracking."+(ott?' Your hands do move out over the backswing path coming down, which usually means an out-to-in path.':''),fix:'Trace a shot with the shot tracer and this section will read your face and path from the ball flight. Until then: a slice points to an open face or an out-to-in path, a hook to a closed face.'};
 const days=Math.round((Date.now()-f.t)/864e5),when=days<1?'today':days===1?'yesterday':days+' days ago';
 let x='';if(f.path<-1&&ott)x=' This matches your swing: your hands come over the top on the way down.';else if(f.path<-1&&inside)x=' Your hands stay inside coming down, so the out-to-in path is more likely from your shoulders or alignment.';else if(f.path>-1&&ott)x=' Your hands do drift out coming down, so watch that this doesn\'t turn into a slice.';
 return{name:k,finding:`From your last traced shot (${when}, a ${String(f.shape||'').toLowerCase()}): clubface about ${f.faceTxt}, path ${f.pathTxt}. ${f.why}${x}`,fix:f.fix}}
function localText(R){
 const m=R.metrics,s=R.scores,C=swingChecks(m),F=SwingMetrics.faults(C),L=SwingMetrics.level(s.overall),fo=m.view==='face-on';
 const categories=AREAS.map(k=>{const cs=C.filter(c=>c.area===k);
  if(k.startsWith('Clubface'))return clubfaceArea(k,m);
  if(!cs.length)return{name:k,finding:'Not measured from this camera angle.',fix:`Film one swing from ${fo?'behind, down the line,':'the front, face-on,'} to check this.`};
  const ws=cs.slice().sort((a,b)=>a.score-b.score),w=ws[0],adv=plainAdvice(w);
  const finding=w.score>=8.5?`${adv.good||'Spot on.'}`:`${plainName(w)}: ${plainState(w).toLowerCase()} (you ${w.shown}; tour players ${w.target}).`+(ws.length>1?` Also checked here: ${ws.slice(1).map(c=>`${plainName(c).toLowerCase()} (${VERDICT[c.verdict][0].toLowerCase()})`).join(', ')}.`:'');
  return{name:k,finding,fix:adv.feel||'Keep doing what you are doing here.'}});
 const o=s.overall,open=o>=9?'Your positions are tour level almost everywhere we can see.':o>=8?'A very good swing with only small things left to tidy up.':o>=7?'A good swing, but there are a couple of clear faults holding you back.':o>=5.5?'There are some real faults here that will be costing you shots, and they can be fixed.':'There are some big faults here costing you a lot of shots. Fix them one at a time and you will see a big difference.';
 const fl=F.slice(0,2).map(f=>{const t=plainAdvice(f).title;return t.charAt(0).toLowerCase()+t.slice(1)});
 const summary=`${open} ${F.length?`The biggest thing to fix is ${fl[0]}${fl[1]?`, then ${fl[1]}`:''}.`:'Nothing is a real fault from this angle, so the gains left are small ones.'}`;
 const top=F[0]||C.filter(c=>c.score<8.5).sort((a,b)=>(8.5-b.score)*b.w-(8.5-a.score)*a.w).map(c=>Object.assign({},c,{advice:SwingMetrics.advice(c)})).find(c=>c.advice&&c.advice.title);
 const strengths=C.filter(c=>c.verdict==='tour').sort((a,b)=>b.w-a.w).slice(0,3).map(c=>plainAdvice(c).good).filter(Boolean);
 return{summary,strengths,top_priority:top?`${plainAdvice(top).title}. ${top.advice.feel}`:'Keep these positions and film again from the other angle.',categories};
}
async function coachText(R){
 const sample=(window.claude&&claude.use)?await claude.use('sample').catch(()=>null):null;if(!sample)return null;
 const m=R.metrics,s=R.scores,C=swingChecks(m),F=SwingMetrics.faults(C);
 const p=`You are a straight-talking golf coach in the style of a popular UK YouTube coach: plain words, honest, encouraging but never flattering. A swing analysis app tracked the golfer's body on one ${m.view} video (${m.handed}-handed) and compared each position with tour players measured on the same tracking.
Checks (score 0-10 against tour players; verdict tour/ok/fault/major): ${JSON.stringify(C.map(c=>({check:c.name,in_plain_words:plainName(c),state:plainState(c),phase:c.phase,area:c.area,you:c.shown,tour:c.target,score:c.score,verdict:c.verdict})))}
Faults in priority order: ${JSON.stringify(F.map(f=>plainAdvice(f).title))}
The reader is an average weekend club golfer, not a coach: write in plain everyday words a 20-handicapper understands. No jargon (if you must use a golf term, explain it in a few words), no degrees or percentages in the summary, strengths or top_priority.
Area scores (do not change): ${JSON.stringify(s)}
Write critical, specific coaching from ONLY these numbers. Be honest: if a position is a fault, say so plainly and say what it does to the ball. Don't praise anything that isn't at tour level. Don't invent things the camera can't see (clubface, grip, ball flight). Don't name drills; the app adds them.
Return ONLY JSON: {"summary":"2 short sentences in plain words, honest overall verdict","strengths":["up to 3 short plain items, only checks that are spot on"],"top_priority":"one plain sentence: the first fault to fix and the feel to fix it","categories":[{"name":"<exact category name>","finding":"one plain sentence; the number can go in brackets","fix":"one sentence feel or cue in plain words"}]} with one entry for each of: ${AREAS.join(', ')}.`;
 const r=await sample.json(p,{modelTier:'default'});
 return r&&Array.isArray(r.categories)?r:null;
}

// ---------- the detailed swing report: fix list, gauges and the position-by-position checklist ----------
const SEV={major:['Costing you lots of shots','bad'],moderate:['Costing you shots','bad'],minor:['Small fix','mid'],polish:['Fine-tune','mid']};
const PHASES=['Setup','Backswing','Top','Downswing','Impact','Finish'];
const PH_KEY={Setup:'Address',Backswing:'Takeaway',Top:'Top',Downswing:'Downswing',Impact:'Impact',Finish:'Finish'};
function swingChecks(m){return m?SwingMetrics.checks(m,m.view):[]}
// ---------- plain English: the same measurements, said the way a weekend golfer would say them ----------
const AREA_PLAIN={'Setup posture':'Setup','Spine angle':'Keeping your posture','Head stability':'Keeping your head steady','Hip and shoulder rotation':'Turning your body','Backswing and top':'Backswing','Tempo and sequencing':'Rhythm and timing','Impact position':'Strike position','Balance and finish':'Balance and finish','Clubface and path (estimate)':'Clubface and swing path'};
const areaName=a=>AREA_PLAIN[a]||String(a||'').replace(' (estimate)','');
