const TEE_COL={white:'#f4f4f0',yellow:'#f1c40f',red:'#d23a2f',blue:'#2c6fd1',black:'#1d1d1d',green:'#2e8b57',purple:'#7d4cc2',gold:'#c9a227',orange:'#e67e22',silver:'#b8bcc2'};
const teeColour=t=>{const c=String(t.colour||'');if(/^#[0-9a-f]{3,6}$/i.test(c))return c;const k=String(t.name||'').toLowerCase().split(/\s+/).find(w=>TEE_COL[w]);return k?TEE_COL[k]:'#9aa59d'};
