async function rtSample(){try{return (window.claude&&claude.use)?await claude.use('sample'):null}catch(_){return null}}
function cleanCourses(r){const a=(r&&Array.isArray(r.courses)?r.courses:[]).filter(c=>c&&c.name).map(c=>({name:String(c.name).slice(0,120),club:String(c.club||'').slice(0,120),town:String(c.town||'').slice(0,80),county:String(c.county||'').slice(0,80),holes:+c.holes===9?9:18,lat:+c.lat||null,lon:+c.lon||null}));
 const seen=new Set();return a.filter(c=>{const k=slug(c.name);if(seen.has(k))return false;seen.add(k);return true}).map(c=>Object.assign(c,{key:slug(c.name)}))}
function cleanCard(r,want){if(!r||!Array.isArray(r.tees))return null;
 const tees=r.tees.map(t=>{const hs=(Array.isArray(t.holes)?t.holes:[]).map((h,i)=>({n:+h.n||i+1,par:Math.min(6,Math.max(3,Math.round(+h.par)||4)),yards:(+h.yards>=40&&+h.yards<=750)?Math.round(+h.yards):null,si:Math.round(+h.si)||null})).sort((a,b)=>a.n-b.n);
  if(hs.length!==9&&hs.length!==18)return null;hs.forEach((h,i)=>h.n=i+1);
  const sis=hs.map(h=>h.si);if(new Set(sis).size!==hs.length||sis.some(s=>!s||s<1||s>18))hs.forEach(h=>h.si=null);
  return{name:String(t.name||'Tees').slice(0,30),colour:teeColour(t),holes:hs}}).filter(Boolean);
 if(!tees.length)return null;
 return{name:want.name,club:want.club||'',town:want.town||r.town||'',county:want.county||'',lat:want.lat||null,lon:want.lon||null,key:want.key,tees,source:'claude',confidence:['high','medium','low'].includes(r.confidence)?r.confidence:'low'}}
function blankCourse(name,holes){const n=holes===9?9:18;return{name:name.trim(),key:slug(name),town:'',tees:[{name:'Yellow',colour:TEE_COL.yellow,holes:Array.from({length:n},(_,i)=>({n:i+1,par:4,yards:null,si:null}))}],source:'you',confidence:'you'}}

