let PCD=null;
function pcdMap(){if(!PCD){PCD=new Map();PCD_RAW.split('\n').forEach(l=>{const [p,a,b,t,g]=l.split('|');PCD.set(p,{pc:p,lat:+a,lon:+b,town:t||'',region:g||''})})}return PCD}
const pcLabel=d=>`${d.town||d.region} (${d.pc})`;
function placeLookup(q){q=String(q||'').trim();if(!q)return null;const u=q.toUpperCase().replace(/\s+/g,' ');
 const m=u.match(/^([A-Z]{1,2}\d[A-Z\d]?)(\s*\d[A-Z]{2})?$/);
 if(m){const d=pcdMap().get(m[1]);return d?{lat:d.lat,lon:d.lon,pc:d.pc,town:d.town||d.region,label:pcLabel(d)}:null}
 const low=q.toLowerCase().replace(/\s+/g,' ');if(low.length<3)return null;if(low==='london'||low==='central london')return placeLookup('WC2N');const all=[...pcdMap().values()];
 const word=s=>new RegExp('(^|\\s)'+low.replace(/[.*+?^${}()|[\]\\]/g,'\\$&')+'(\\s|$)').test(s.toLowerCase());
 const d=all.find(d=>d.town.toLowerCase()===low)||all.find(d=>d.region.toLowerCase()===low)||all.find(d=>word(d.region))||all.find(d=>word(d.town));
 return d?{lat:d.lat,lon:d.lon,pc:d.pc,town:d.town||d.region,label:d.town||d.region}:null}
async function placeFromClaude(q){const s=await rtSample();if(!s)return null;
 try{const r=await s.json(`Give the approximate centre of this place in the United Kingdom: "${q.replace(/"/g,"'")}". If it isn't a real UK town, village or area, set found to false. Return ONLY JSON: {"found":true,"name":"Town, County","lat":0,"lon":0}`,{modelTier:'quick'});
  if(r&&r.found!==false&&+r.lat>49&&+r.lat<61.5&&+r.lon>-9&&+r.lon<2.5)return{lat:+r.lat,lon:+r.lon,pc:'',town:String(r.name||q).split(',')[0],label:String(r.name||q).split(',')[0]}}catch(_){}return null}
async function rtGetPlace(){try{await Store.init();if(Store.mode==='db'){const d=await Store.col().doc('where').get();if(d.exists)return d.data()}}catch(_){}return Store.lget('cc_where',null)}
async function rtSetPlace(p){const v={label:p.label,lat:p.lat,lon:p.lon,pc:p.pc||'',town:p.town||'',kind:'place'};try{Store.lset('cc_where',v)}catch(_){}
 try{await Store.init();if(Store.mode==='db')await Store.col().doc('where').set(v)}catch(e){console.error(e)}}
function gpsBlocked(){try{const fp=document.featurePolicy||document.permissionsPolicy;return !!(fp&&fp.allowsFeature&&!fp.allowsFeature('geolocation'))}catch(_){return false}}
async function rtNearby(){RT.msg=null;RT.results=null;RT.askPlace=false;let loc=null;
 if(!gpsBlocked()&&navigator.geolocation){RT.busy='Finding your location…';rtRender();
  try{const pos=await new Promise((ok,no)=>navigator.geolocation.getCurrentPosition(ok,no,{enableHighAccuracy:false,timeout:10000,maximumAge:300000}));loc={lat:pos.coords.latitude,lon:pos.coords.longitude,label:'',gps:1}}catch(_){}}
 if(!loc&&RT.place)loc=RT.place;
 if(!loc){RT.busy='';RT.askPlace=true;rtRender();setTimeout(()=>{const i=$('rtPlace');if(i)i.focus()},40);return}
 return rtCoursesNear(loc)}
async function rtCoursesNear(loc){const {lat,lon}=loc;RT.here={lat,lon};RT.hereLabel=loc.label||'';RT.msg=null;RT.results=null;
 if(lat<49.8||lat>61||lon<-8.7||lon>2)RT.msg={t:'You look to be outside the UK, so these are the closest UK courses Claude knows.'};
 RT.busy='Looking for courses near you…';rtRender();if(!HOSTED_IN_CLAUDE)return osmNear(loc);
 const s=await rtSample();if(!s){RT.busy='';const cs=rtExtraNear(lat,lon,[]).sort((a,b)=>a.mi-b.mi);RT.results=cs;RT.area=loc.label||'';RT.msg={bad:!cs.length,t:'Course finder needs Claude, which isn\'t available here'+(cs.length?', so only courses already in the app are listed.':'. Add your course yourself below.')};return rtRender()}
 try{const r=await s.json(`You help golfers in the United Kingdom find golf courses near them. The golfer is at latitude ${lat.toFixed(4)}, longitude ${lon.toFixed(4)}${loc.town?` (near ${loc.town}${loc.pc?`, postcode district ${loc.pc}`:''})`:''}.
List up to 20 real golf courses you are confident exist within about 20 miles, nearest first, including small members' clubs and municipal courses, not just well-known ones. Skip driving ranges, footgolf and pitch-and-putt unless there is nothing else. Where a club has more than one course, list each course separately and include the course name (for example "St Andrews Links – Old Course"). Give each course's approximate latitude and longitude.
Return ONLY JSON: {"area":"nearest town, county","courses":[{"name":"","club":"","town":"","county":"","holes":18,"lat":0,"lon":0}]}`,{modelTier:'default'});
  let cs=cleanCourses(r);cs.forEach(c=>{c.mi=c.lat!=null&&c.lon!=null?miles(lat,lon,c.lat,c.lon):null});cs=rtExtraNear(lat,lon,cs).filter(c=>c.mi==null||c.mi<=40);cs.sort((a,b)=>(a.mi??999)-(b.mi??999));
  RT.area=String(r&&r.area||'')||loc.label;RT.results=cs;RT.busy='';if(!cs.length)RT.msg={bad:1,t:'No courses came back for this area. Search by course or town instead.'}}
 catch(e){RT.busy='';RT.msg={bad:1,t:rtErr(e)}}
 rtRender()}
function rtExtraNear(lat,lon,cs){const have=new Set(cs.map(c=>c.key)),names=cs.map(c=>c.name.toLowerCase());
 const pool=KNOWN_COURSES.concat(RT.myCourses||[]).filter(c=>c&&c.lat!=null&&c.lon!=null);
 for(const c of pool){if(have.has(c.key))continue;const short=c.name.toLowerCase().replace(/\s*golf club$/,'');if(names.some(n=>n.includes(short)))continue;
  const mi=miles(lat,lon,c.lat,c.lon);if(mi<=25){cs.push({name:c.name,club:c.club||'',town:c.town||'',county:c.county||'',holes:c.tees[0].holes.length,lat:c.lat,lon:c.lon,key:c.key,mi});have.add(c.key)}}
 return cs}
function rtExtraSearch(q,cs){const w=q.toLowerCase().split(/\s+/).filter(x=>x.length>1&&!['golf','club','gc','the','course'].includes(x));if(!w.length)return cs;const have=new Set(cs.map(c=>c.key).concat(cs.map(c=>keyBase(c.key))));
 const hits=KNOWN_COURSES.concat(RT.myCourses||[]).filter(c=>c&&!have.has(c.key)&&!have.has(keyBase(c.key))&&w.every(x=>(c.name+' '+(c.town||'')+' '+(c.county||'')).toLowerCase().includes(x)));
 return hits.map(c=>({name:c.name,club:c.club||'',town:c.town||'',county:c.county||'',holes:c.tees[0].holes.length,lat:c.lat,lon:c.lon,key:c.key})).concat(cs)}
async function rtSearch(q){q=String(q||'').trim();RT.query=q;if(q.length<2){RT.msg={bad:1,t:'Type at least two letters of a course, club or town.'};return rtRender()}
 RT.msg=null;RT.results=null;RT.area='';RT.busy=`Searching for “${q}”…`;rtRender();if(!HOSTED_IN_CLAUDE)return osmSearch(q);
 const s=await rtSample();if(!s){RT.busy='';RT.results=rtExtraSearch(q,[]);RT.msg=RT.results.length?null:{bad:1,t:'Course search needs Claude, which isn\'t available here. Add your course yourself below.'};return rtRender()}
 try{const r=await s.json(`You help golfers in the United Kingdom find golf courses. Find real UK golf courses matching "${q.replace(/"/g,"'")}" – it may be a course name, club name or a town. List up to 10, best match first (for a town, the courses in and around it). Where a club has more than one course, list each course separately with the course name. Give each course's approximate latitude and longitude.
Return ONLY JSON: {"courses":[{"name":"","club":"","town":"","county":"","holes":18,"lat":0,"lon":0}]}`,{modelTier:'default'});
  const cs=rtExtraSearch(q,cleanCourses(r));if(RT.here)cs.forEach(c=>{c.mi=c.lat!=null&&c.lon!=null?miles(RT.here.lat,RT.here.lon,c.lat,c.lon):null});
  RT.results=cs;RT.busy='';if(!cs.length)RT.msg={bad:1,t:`No UK courses matched “${q}”. Check the spelling, try the town, or add the course yourself below.`}}
 catch(e){RT.busy='';RT.msg={bad:1,t:rtErr(e)}}
 rtRender()}
function rtErr(e){const c=e&&e.code;return c==='not_granted'?'Claude wasn\'t allowed to help with this. You can still add the course yourself below.':c==='rate_limited'?'Too many requests just now. Wait a minute and try again.':c==='cancelled'?'Cancelled.':'Something went wrong talking to Claude. Try again in a moment.'}

