async function rtLoadRounds(){try{RT.rounds=await RStore.list()}catch(e){console.error(e);RT.rounds=[]}if(RT.tab==='mine')rtRender();else{const n=$('rtCount');if(n)n.textContent=RT.rounds.length||''}}
async function rtLoadMyCourses(){try{await Store.init();let a=[];if(Store.mode==='db'){const q=await Store.col().where('kind','==','course').limit(50).get();a=q.docs.map(d=>d.data())}
 else if(Store.mode==='local'){for(let i=0;i<localStorage.length;i++){const k=localStorage.key(i);if(k&&k.startsWith('cc_course_'))a.push(Store.lget(k,null))}}else a=Object.values(Store.mem.courses||{});
 RT.myCourses=a.filter(c=>c&&c.tees&&c.tees.length).sort((x,y)=>(y.updatedAt||0)-(x.updatedAt||0))}catch(e){RT.myCourses=[]}}
