 if(d.palStep){const [k,dv]=d.palStep.split(':').map(Number),r=RT.live,p=r.others[k],h=r.holes[r.i];p.sc[r.i]=Math.max(1,Math.min(20,(p.sc[r.i]??h.par)+(p.sc[r.i]==null?0:dv)));rtSaveLive();rtRender();return}
