  f.querySelectorAll('[data-ce]').forEach(inp=>{const h=t.holes[+inp.dataset.i],v=inp.value.trim();if(inp.dataset.ce==='par')h.par=+v||4;else if(inp.dataset.ce==='yards')h.yards=(+v>=40&&+v<=750)?Math.round(+v):null;else h.si=(+v>=1&&+v<=18)?Math.round(+v):null});
