function flipWords(root,L){if(!root)return;const tw=document.createTreeWalker(root,NodeFilter.SHOW_TEXT);let n;
 while((n=tw.nextNode())){if(!FLIPPED.has(n))FLIPPED.set(n,n.nodeValue);const o=FLIPPED.get(n);n.nodeValue=L?o.replace(/\b(left|right|Left|Right)\b/g,w=>LR_SWAP[w]):o}}
