const BG={bag:null,sel:null,edit:false,editBag:false,err:'',which:''};
// Your bag is kept on the phone and also saved online with your profile, so it comes back wherever you log in:
// in Safari or from the home-screen icon, on a new phone, or after the phone clears website data.
