const BagCloud={
 on(){return SB.on()&&!!Store.user},
 key(){return 'bag~'+Store.user},
 async pull(){const rows=await sbGet('course_cards',`course_key=eq.${encodeURIComponent(this.key())}&select=card,created_at&order=created_at.desc&limit=6`);
  return (rows||[]).map(r=>r.card).filter(c=>c&&Array.isArray(c.clubs)&&c.yards).sort((a,b)=>(b.updatedAt||0)-(a.updatedAt||0))[0]||null},
 push(b){if(!this.on())return;clearTimeout(this.t);const snap={clubs:b.clubs.slice(),yards:JSON.parse(JSON.stringify(b.yards)),updatedAt:b.updatedAt||Date.now(),hand:b.hand||Hand.get()};
  this.t=setTimeout(()=>sbSend('course_cards',[{course_key:this.key(),name:'My bag',card:snap,device:SB.device()}]),800)}};
const bagClean=b=>{b=b||{clubs:BAG_DEFAULT.slice(),yards:{}};b.clubs=(b.clubs||[]).filter(id=>BAG_CLUBS.some(c=>c.id===id));b.yards=b.yards||{};return b};
const BagStore={
 local(){if(Store.mode==='db')return null;return Store.mode==='local'?Store.lget('cc_bag',null):Store.mem.bag||null},
 keepLocal(b){if(Store.mode==='local'){try{Store.lset('cc_bag',b);return}catch(_){Store.mode='memory'}}if(Store.mode!=='db')Store.mem.bag=b},
 async load(){await Store.init();let b=null;
  if(Store.mode==='db'){try{const d=await Store.col().doc('bag').get();b=d.exists?d.data():null}catch(_){}}
  else b=this.local();
  if(BagCloud.on()){
   const merge=c=>{if(c&&(!b||!b.updatedAt||(c.updatedAt||0)>b.updatedAt)){const nb=Object.assign({kind:'bag'},c);this.keepLocal(nb);if(nb.hand&&nb.hand!==Hand.get()){Hand.setLocal(nb.hand);applyHand()}return nb}
    if(b&&b.updatedAt&&(!c||b.updatedAt>(c.updatedAt||0)))BagCloud.push(b);return null};
   const pull=BagCloud.pull().catch(()=>undefined);
   const c=await Promise.race([pull,sleep(2500).then(()=>'late')]);
   if(c==='late')pull.then(c2=>{if(c2===undefined)return;const nb=merge(c2);if(nb){BG.bag=bagClean(nb);if(!$('p9').hidden&&!BG.edit)initBag()}});
   else if(c!==undefined){const nb=merge(c);if(nb)b=nb}}
  return bagClean(b)},
 async save(b){await Store.init();b.kind='bag';b.updatedAt=Date.now();BagCloud.push(b);
  if(Store.mode==='db'){await Store.col().doc('bag').set(b);return}
  this.keepLocal(b)}};
const bagOrder=ids=>BAG_CLUBS.filter(c=>ids.includes(c.id)).map(c=>c.id);
function clubFor(yds,bag){bag=bag||BG.bag;if(!bag||!yds)return null;const opts=bag.clubs.map(id=>({id,c:(bag.yards[id]||{}).carry})).filter(o=>o.c);if(!opts.length)return null;
 opts.sort((a,b)=>Math.abs(a.c-yds)-Math.abs(b.c-yds));return opts[0]}
// typical carries for a club golfer, used until you've entered your own
const TYPICAL_CARRY={D:220,'3W':200,'5W':185,'7W':175,'2H':190,'3H':180,'4H':170,'5H':160,'2i':185,'3i':175,'4i':165,'5i':158,'6i':150,'7i':140,'8i':130,'9i':120,PW:110,GW:100,'48':105,'50':100,'52':92,'54':85,'56':78,'58':70,'60':63,'64':52};
// the club for a distance: your own yardages if you've added any, otherwise typical ones
function clubPick(yds){const b=BG.bag||{clubs:BAG_DEFAULT.slice(),yards:{}};if(!yds||yds<15)return null;
 const own=b.clubs.some(id=>(b.yards[id]||{}).carry);
 const opts=b.clubs.map(id=>({id,c:own?(b.yards[id]||{}).carry:TYPICAL_CARRY[id]})).filter(o=>o.c);if(!opts.length)return null;
 const longest=opts.reduce((a,o)=>o.c>a.c?o:a);
 if(yds>longest.c+12)return{id:longest.id,c:longest.c,own,short:yds-longest.c};
 opts.sort((a,b)=>Math.abs(a.c-yds)-Math.abs(b.c-yds));const o=opts[0];return{id:o.id,c:o.c,own,diff:o.c-yds}}
function clubHTML(yds,lab){const k=clubPick(yds);if(!k)return '';
 const note=k.short?`won't reach: ${k.short} yds short, so play to a safe spot`:Math.abs(k.diff)>=6?`carries ${k.c} (${Math.abs(k.diff)} ${k.diff>0?'long':'short'})`:`carries ${k.c}`;
 return `<div class="gpsClub"><span class="gpsClubK">${esc(lab||'Club')}</span><b>${esc(clubName(k.id))}</b><span class="gpsClubN">${esc(note)}${k.own?'':' · typical distance'}</span></div>`}
