// ---------- Course GPS: satellite hole map, live position, distance to the middle of the green ----------
// Runs where the page may use location and load map imagery (the standalone Caddy Coach app).
// Inside Claude both are blocked, so the map explains that instead.
const GPS={map:null,me:null,acc:null,green:null,tap:null,lines:null,labels:[],watch:null,pos:null,setMode:false,course:null,wake:null,tiles:0,tileErr:0};
const HOSTED_IN_CLAUDE=!!(window.claude&&window.claude.use);
const YD=1760;const ydsBetween=(a,b)=>Math.round(miles(a.lat,a.lng??a.lon,b.lat,b.lng??b.lon)*YD);
function loadLeaflet(){if(window.L)return Promise.resolve(window.L);return addScript('https://cdnjs.cloudflare.com/ajax/libs/leaflet/1.9.4/leaflet.min.js').then(()=>window.L)}
