if(!HOSTED_IN_CLAUDE){const f=$('rtFoot');if(f)f.innerHTML='Course data © <a href="https://www.openstreetmap.org/copyright" target="_blank" rel="noopener">OpenStreetMap contributors</a>. Rounds and the cards you edit are saved on this phone.'}

// ---------- learning greens from your round (standalone): where you spend a minute before entering your score is the green ----------
const TRK={watch:null,fixes:[],start:{},hole:null};
function trkStart(){if(HOSTED_IN_CLAUDE||TRK.watch!=null||!navigator.geolocation||!RT.live)return;gpsCourse().then(c=>c&&setTimeout(gfEnsure,1500)).catch(()=>{});
 TRK.watch=navigator.geolocation.watchPosition(p=>{const f={t:Date.now(),lat:p.coords.latitude,lon:p.coords.longitude,acc:p.coords.accuracy};TRK.fixes.push(f);TRK.fixes=TRK.fixes.filter(x=>f.t-x.t<600000);
  const r=RT.live;if(!r)return;const h=r.holes[r.i];if(TRK.hole!==h.n){TRK.hole=h.n;TRK.start[h.n]=null}if(!TRK.start[h.n]&&f.acc<25)TRK.start[h.n]={lat:f.lat,lon:f.lon}},()=>{},{enableHighAccuracy:true,maximumAge:5000,timeout:30000})}
function trkStop(){if(TRK.watch!=null){navigator.geolocation.clearWatch(TRK.watch);TRK.watch=null}TRK.fixes=[];TRK.start={};TRK.hole=null}
async function trkLearn(h){if(HOSTED_IN_CLAUDE||!RT.live)return;const now=Date.now(),all=TRK.fixes.filter(f=>now-f.t<100000&&f.acc<20).sort((a,b)=>a.t-b.t);if(all.length<4)return;
 let pts=[];for(const a of all){const c=all.filter(f=>mBetween(a,f)<22);if(c.length>=pts.length)pts=c}if(pts.length<4)return;
 const cen={lat:pts.reduce((a,f)=>a+f.lat,0)/pts.length,lon:pts.reduce((a,f)=>a+f.lon,0)/pts.length};
 const st=TRK.start[h.n];if(st&&h.yards){const d=mBetween(st,cen)*1.09361;if(d<h.yards*.55||d>h.yards*1.35)return}
 const c=await gpsCourse();if(!c)return;const ex=c.greens&&c.greens[h.n];if(ex&&!ex.learned&&!ex.shared)return;
 let spot=cen;const pl=(c.greenPool||[]).concat(c.gf&&c.gf.cands||[]);if(pl.length){const near=pl.map(g=>({g,d:mBetween(cen,g)})).sort((a,b)=>a.d-b.d)[0];if(near&&near.d<30)spot=near.g}
 const got={lat:+spot.lat.toFixed(6),lon:+spot.lon.toFixed(6),learned:spot===cen};sbShareHole(c,h.n,got,'learned');if(ex&&ex.shared)return;// golfers have already mapped it: your putting spot just adds a vote
 c.greens=c.greens||{};c.greens[h.n]=got;await RStore.saveCourse(c).catch(()=>{});toast(`Hole ${h.n} green saved from your round. Distances to it are automatic from now on.`)}
function toast(t){buzz(12);let el=$('ccToast');if(!el){el=document.createElement('div');el.id='ccToast';el.className='ccToast';el.setAttribute('role','status');document.body.appendChild(el)}el.textContent=t;el.classList.add('show');clearTimeout(el._t);el._t=setTimeout(()=>el.classList.remove('show'),3800)}
